CREATE TABLE approval_members (
  id bigserial PRIMARY KEY, telegram_user_id bigint UNIQUE NOT NULL,
  active boolean NOT NULL DEFAULT true, limit_minor bigint NOT NULL CHECK (limit_minor >= 0)
);
CREATE TABLE purchase_requests (
  id bigserial PRIMARY KEY, version integer NOT NULL DEFAULT 1,
  author_id bigint NOT NULL, approver_id bigint NOT NULL REFERENCES approval_members(id),
  total_minor bigint NOT NULL CHECK (total_minor >= 0), snapshot jsonb NOT NULL,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected'))
);
CREATE TABLE approval_events (
  id bigserial PRIMARY KEY, request_id bigint NOT NULL REFERENCES purchase_requests(id),
  request_version integer NOT NULL, previous_status text NOT NULL, decision text NOT NULL,
  actor_id bigint NOT NULL, telegram_user_id bigint NOT NULL,
  comment text NOT NULL, decided_at timestamptz NOT NULL,
  UNIQUE (request_id, request_version)
);
CREATE TABLE approval_outbox (
  event_id bigint NOT NULL REFERENCES approval_events(id), kind text NOT NULL,
  state text NOT NULL DEFAULT 'pending', PRIMARY KEY (event_id, kind)
);
